responses.text:
{
  "decision": "applies",
  "reasons": [
    "Applies because you sell furniture and wooden goods and leather goods — wood and cattle leather are both covered commodities.",
    "You place these products on the EU market from Germany, so you count as an operator or trader from 30 June 2026."
  ],
  "todos": [
    {
      "text": "Ask each furniture and leather supplier for plot geolocation and origin evidence",
      "due": "2026-01-01",
      "quote": "the geolocation of all plots of land where the relevant commodities that the relevant product contains, or has been made using, were produced"
    },
    {
      "text": "Set up a folder per product line and keep due-diligence documents for five years",
      "due": "2026-06-30",
      "quote": "Operators shall keep for at least 5 years from the date of the placing on the market or export of the relevant products all documentation related to due diligence"
    }
  ]
}
